using System;using System.IO;using System.Collections.Generic;using Bokumyaku.Simulation;
public static class FirstWeekWeaponCheck{
 public static object Run(){var rows=new List<object>();foreach(int seed in new[]{42,73,101})foreach(WeaponKind weapon in Enum.GetValues(typeof(WeaponKind))){var run=new RunSimulator(seed,new MetaProgress{Damage=9,Supply=9,Growth=9,Harvest=9});run.SetBuild(BuildPreset.Record);run.SetWeapon(weapon);int peak=0;for(int i=0;i<90000&&run.State==RunStatus.Running;i++){run.Tick();peak=Math.Max(peak,run.Enemies.Count);}rows.Add(new{seed,weapon=weapon.ToString(),state=run.State.ToString(),wave=run.CompletedWave,seconds=run.TickCount/30.0,run.Kills,leaks=run.LeakedByType,peakEnemies=peak,run.RunInk,levels=run.UpgradeLevels});}var sensitivity=new List<object>();foreach(int seed in new[]{42,73,101})foreach(int axis in new[]{0,1,2}){var meta=new MetaProgress{Damage=9,Supply=9,Growth=9,Harvest=9};if(axis==0)meta.Damage=20;else if(axis==1)meta.Supply=20;else meta.Growth=20;var probe=new RunSimulator(seed,meta);probe.SetBuild(BuildPreset.Record);probe.SetWeapon(WeaponKind.Point);for(int i=0;i<90000&&probe.State==RunStatus.Running;i++)probe.Tick();sensitivity.Add(new{seed,axis=((MetaUpgrade)axis).ToString(),wave=probe.CompletedWave,state=probe.State.ToString(),leaks=probe.LeakedByType});}File.WriteAllText(Path.GetFullPath("../docs/evidence/first-week-weapons.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{method="Equal meta9 in all four research, Record build, six weapons and three seeds; diagnostic capacity, not funded first-week path. Bounded 90000 ticks; unfinished runs explicitly marked.",rows,sensitivity},Newtonsoft.Json.Formatting.Indented));return sensitivity;}
}
